@Isolated("Replaces the process-wide SPARQL parser provider")
@Execution(ExecutionMode.SAME_THREAD)
class SparqlQueryParserCacheGraphModeTest {

	@Test
	void sameCachedTextUsesTheTargetConnectionMode() {
		MemoryStore store = new MemoryStore();
		store.init();
		try (var builtin = store.getConnection()) {
			var unknown = new NotifyingSailConnectionWrapper(builtin) {
			};
			String query = "SELECT ?a WHERE { GRAPH <urn:absent-cache-test> { BIND(<urn:a> AS ?a) } }";

			assertThat(count(query, unknown)).isEqualTo(1);
			assertThat(count(query, builtin)).isZero();
			assertThat(count(query, unknown)).isEqualTo(1);
			assertThat(count(query, builtin)).isZero();
		} finally {
			store.shutDown();
		}
	}

	@Test
	void cachedAlgebraIsClonedAndExplicitModesRemainIsolated() {
		String query = "SELECT ?g WHERE { GRAPH ?g {} }";
		QueryParseOptions graphOptions = QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH);
		var first = SparqlQueryParserCache.get(query, graphOptions);
		first.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Graph graph) {
				graph.setGraphName(Var.of("changed"));
			}
		});
		var second = SparqlQueryParserCache.get(query, graphOptions);
		assertThat(second).isNotSameAs(first).isNotEqualTo(first);
		assertThat(second.getBindingNames()).contains("g");
		assertThat(SparqlQueryParserCache.get(query, QueryParseOptions.DEFAULT).toString()).doesNotContain("Graph");
	}

	@Test
	void replacementProviderDoesNotReuseAnEarlierProvidersLegacyTree() {
		QueryParserRegistry registry = QueryParserRegistry.getInstance();
		QueryParserFactory original = registry.get(QueryLanguage.SPARQL).orElseThrow();
		String query = "SELECT ?oldProvider WHERE { VALUES ?oldProvider { <urn:value> } }";
		assertThat(SparqlQueryParserCache.get(query).getBindingNames()).containsExactly("oldProvider");
		try {
			registry.add(legacyFactory(original));
			assertThat(SparqlQueryParserCache.get(query).getBindingNames()).containsExactly("newProvider");
		} finally {
			registry.add(original);
		}
		assertThat(SparqlQueryParserCache.get(query).getBindingNames()).containsExactly("oldProvider");
	}

	@Test
	void builtinConnectionUsesLegacyWithAnUnknownParserProvider() {
		QueryParserRegistry registry = QueryParserRegistry.getInstance();
		QueryParserFactory original = registry.get(QueryLanguage.SPARQL).orElseThrow();
		MemoryStore store = new MemoryStore();
		store.init();
		try (var connection = store.getConnection()) {
			String query = "SELECT ?a WHERE { GRAPH <urn:absent-provider-test> { BIND(<urn:a> AS ?a) } }";
			assertThat(count(query, connection)).isZero();
			try {
				registry.add(legacyFactory(original));
				assertThat(count(query, connection)).isEqualTo(1);
			} finally {
				registry.add(original);
			}
			assertThat(count(query, connection)).isZero();
		} finally {
			store.shutDown();
		}
	}

	private static QueryParserFactory legacyFactory(QueryParserFactory delegate) {
		return new QueryParserFactory() {
			@Override
			public QueryLanguage getQueryLanguage() {
				return QueryLanguage.SPARQL;
			}

			@Override
			public QueryParser getParser() {
				return new QueryParser() {
					@Override
					public ParsedQuery parseQuery(String query, String baseURI) {
						return delegate.getParser().parseQuery(query.replace("oldProvider", "newProvider"), baseURI);
					}

					@Override
					public ParsedUpdate parseUpdate(String update, String baseURI) {
						return delegate.getParser().parseUpdate(update, baseURI);
					}
				};
			}
		};
	}

	private static long count(String query, SailConnection connection) {
		Resource[] contexts = { null };
		Select select = new Select(connection, query,
				row -> new ValidationTuple(row.getValue("a"), ConstraintComponent.Scope.nodeShape, false, contexts),
				contexts, false);
		select.receiveLogger(ValidationExecutionLogger.getInstance(false));
		try (var rows = select.iterator()) {
			return rows.stream().count();
		}
	}
}
